import { describe, it, expect } from "vitest";
import {
  recordStop, activeStops, isFaultStop, stopTone, stopHeadline, stopLogLine,
  STOP_NOTICE_MS, MAX_STOPS, type PaneStop, type StopReason,
} from "@/app/console/lib/paneStops";

const stop = (paneId: string, reason: StopReason, at: number): PaneStop =>
  ({ paneId, reason, detail: `${reason} detail`, at });

describe("the stop ledger (#a-stopped-session-says-why)", () => {
  it("keeps a stop for exactly the notice window, then drops it", () => {
    const t = 1_000_000;
    const list = recordStop([], stop("p:a", "failed", t), t);
    expect(activeStops(list, t)).toHaveLength(1);
    expect(activeStops(list, t + STOP_NOTICE_MS - 1)).toHaveLength(1);
    // The maintainer asked for "5 seconds max" — at the boundary it is gone, not fading.
    expect(activeStops(list, t + STOP_NOTICE_MS)).toHaveLength(0);
  });

  it("REPLACES an earlier stop for the same pane rather than stacking", () => {
    // The reported worker stopped NINE times in one run. Nine notices for one pane is the same
    // information nine times while whatever else stopped scrolls out of reach.
    const t = 5_000;
    let list = recordStop([], stop("p:a", "failed", t), t);
    list = recordStop(list, stop("p:a", "signalled", t + 100), t + 100);
    expect(list).toHaveLength(1);
    expect(list[0].reason).toBe("signalled");
  });

  it("keeps DIFFERENT panes side by side, newest first", () => {
    const t = 5_000;
    let list = recordStop([], stop("p:a", "failed", t), t);
    list = recordStop(list, stop("p:b", "reaped", t + 10), t + 10);
    const active = activeStops(list, t + 20);
    expect(active.map((s) => s.paneId)).toEqual(["p:b", "p:a"]);
  });

  it("prunes expired entries as it records, so the ledger cannot grow unattended", () => {
    const t = 0;
    let list = recordStop([], stop("p:old", "failed", t), t);
    const later = t + STOP_NOTICE_MS + 1;
    list = recordStop(list, stop("p:new", "failed", later), later);
    expect(list.map((s) => s.paneId)).toEqual(["p:new"]);
  });

  it("caps the ledger — a fleet relaunch can stop a dozen panes at once", () => {
    let list: PaneStop[] = [];
    for (let i = 0; i < MAX_STOPS + 5; i++) list = recordStop(list, stop(`p:${i}`, "failed", 100 + i), 100 + i);
    expect(list).toHaveLength(MAX_STOPS);
    // The OLDEST are the ones dropped.
    expect(list[list.length - 1].paneId).toBe(`p:${MAX_STOPS + 4}`);
  });

  /// THE REGRESSION THAT KEEPS THIS USEFUL. Every session ends eventually; a notice on all of them
  /// is one the user learns to ignore, and the real failures hide among them.
  it("does NOT treat a finished or deliberately-closed session as a fault", () => {
    for (const r of ["finished", "app-closed", "auto-ended", "reaped", "disabled"] as StopReason[]) {
      expect(isFaultStop(r), `${r} is routine`).toBe(false);
      expect(stopTone(r)).toBe("neutral");
    }
  });

  it("DOES treat a real failure as a fault, and shouts loudest when the agent never ran", () => {
    for (const r of ["failed", "signalled", "unknown"] as StopReason[]) {
      expect(isFaultStop(r), `${r} is a fault`).toBe(true);
      expect(stopTone(r)).toBe("warn");
    }
    // The agent never started and the fix is on the HOST — a different problem from a session that
    // ran and died, so it does not share their tone.
    expect(stopTone("launcher-failed")).toBe("danger");
    expect(stopTone("quarantined")).toBe("danger");
  });

  it("gives every reason a headline — a new reason cannot ship unphrased", () => {
    const all: StopReason[] = [
      "finished", "failed", "signalled", "launcher-failed", "app-closed",
      "unknown", "reaped", "auto-ended", "quarantined", "disabled",
    ];
    for (const r of all) {
      const h = stopHeadline(r);
      expect(h, `${r} needs a headline`).toBeTruthy();
      expect(h).not.toContain("undefined");
    }
  });

  it("logs the pane, the reason and the detail — the record that outlives the five seconds", () => {
    const line = stopLogLine(stop("network-monitor:domain-model-and-adapter-traits", "failed", 1));
    expect(line).toContain("network-monitor:domain-model-and-adapter-traits");
    expect(line).toContain("failed");
    expect(line).toContain("failed detail");
  });
});

describe("the last words (#a-stopped-session-shows-its-last-words)", () => {
  const at = 1_000;

  it("puts a fault's last output in the log line — the copy still there tomorrow", () => {
    const line = stopLogLine({ paneId: "p:a", reason: "failed", detail: "exited 1", at, lastOutput: "Error: credentials expired" });
    expect(line).toContain("Error: credentials expired");
  });

  it("SAYS a session printed nothing rather than leaving an absence", () => {
    // A worker that died silently is itself the finding — an empty quote reads as a broken banner.
    const line = stopLogLine({ paneId: "p:a", reason: "failed", detail: "exited 1", at });
    expect(line).toContain("(printed nothing)");
  });

  it("never quotes output for a stop that was NOT a fault", () => {
    for (const reason of ["finished", "app-closed", "reaped", "auto-ended", "disabled"] as StopReason[]) {
      const line = stopLogLine({ paneId: "p:a", reason, detail: "d", at, lastOutput: "should not appear" });
      expect(line, `${reason} must not quote output`).not.toContain("should not appear");
      expect(line).not.toContain("printed nothing");
    }
  });
});

// Many stops must render as ONE banner (`one-stop-banner-per-pane-fills-the-screen`).
//
// The events that end several sessions at once — an app relaunch, a fleet stop, a reaper sweep after
// the renderer dies — are exactly the ones that used to fill the screen with full-width bars, so the
// worst display coincided with the worst moment.
import { describe, it, expect } from "vitest";
import { stopsForNotice, stopSummary, type PaneStop } from "@/app/console/lib/paneStops";

const NOW = 1_000_000;
const stop = (paneId: string, reason: PaneStop["reason"], atOffset = 0, lastOutput?: string): PaneStop =>
  ({ paneId, reason, detail: "d", at: NOW - atOffset, lastOutput }) as PaneStop;

describe("collapsing many stops", () => {
  it("puts FAULTS first, whatever the order they arrived in", () => {
    // A fault carries its last words, and nothing else in the app has them once the pane is
    // recreated. Burying an exit=1 under six routine closes is how the one line worth reading
    // goes unread.
    const list = [
      stop("a:1", "app-closed", 100),
      stop("b:2", "app-closed", 50),
      stop("c:3", "failed", 400, "panic: boom"),
      stop("d:4", "app-closed", 10),
    ];
    const ordered = stopsForNotice(list, NOW);
    expect(ordered[0].paneId).toBe("c:3");
    expect(ordered[0].reason).toBe("failed");
  });

  it("orders the rest newest-first behind the faults", () => {
    const list = [stop("a:1", "app-closed", 300), stop("b:2", "app-closed", 10)];
    expect(stopsForNotice(list, NOW).map((s) => s.paneId)).toEqual(["b:2", "a:1"]);
  });

  it("summarises BY REASON, not by pane id", () => {
    // The ids are in the rows; this line answers "what happened to my sessions", which is a reason.
    const list = [
      stop("a:1", "app-closed", 10),
      stop("b:2", "app-closed", 20),
      stop("c:3", "reaped", 30),
    ];
    const s = stopSummary(stopsForNotice(list, NOW));
    expect(s).toContain("3 sessions stopped");
    expect(s).toContain("2 closed by the app");
    expect(s).toContain("1 reclaimed while idle");
    expect(s).not.toContain("a:1");
  });

  it("names the fault's reason first in the summary too", () => {
    const list = [stop("a:1", "app-closed", 10), stop("c:3", "failed", 20, "boom")];
    expect(stopSummary(stopsForNotice(list, NOW)).indexOf("error"))
      .toBeLessThan(stopSummary(stopsForNotice(list, NOW)).indexOf("closed by the app"));
  });

  it("reads naturally for a single stop", () => {
    expect(stopSummary(stopsForNotice([stop("a:1", "finished", 10)], NOW))).toContain("1 session stopped");
  });

  it("drops stops past the notice window, so the banner cannot grow forever", () => {
    const old = stop("old:1", "app-closed", 60_000);
    const fresh = stop("new:1", "app-closed", 100);
    expect(stopsForNotice([old, fresh], NOW).map((s) => s.paneId)).toEqual(["new:1"]);
  });

  it("is empty when nothing is active, so the banner does not render at all", () => {
    expect(stopsForNotice([stop("x:1", "app-closed", 60_000)], NOW)).toEqual([]);
    expect(stopSummary([])).toBe("");
  });
});

// The stop ledger, captured from the LIVE TypeScript so the Rust port can be proved equal.
//
// Rust already supplies every FACT this reasons over: `console/pty/pump.rs` emits `pty_exit_<pane>`
// knowing the exit code, the signal and whether the cage launcher died before the agent ran; it phrases
// the `detail`; it sanitizes the last output. What ran here is the JUDGEMENT on those facts.
//
// THE JUDGEMENT IS THE POINT. The routine/fault split is what stops the feature becoming noise — every
// session ends eventually, so a banner firing on all of them is one the user learns to ignore, and the
// real failures hide among them. `finished` is a SUCCESS.
//
//     UPDATE_FIXTURES=1 npx vitest run .bsc-records/app/console/lib/paneStops.2.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  isFaultStop, recordStop, activeStops, stopLogLine, STOP_NOTICE_MS, MAX_STOPS,
} from "@/app/console/lib/paneStops";
import type { PaneStop, StopReason } from "@/app/console/lib/paneStops";

const FIXTURE = join(process.cwd(), "src/app/console/lib/stopLedger.fixtures.json");

const REASONS: StopReason[] = [
  "finished", "failed", "signalled", "launcher-failed", "app-closed",
  "unknown", "reaped", "auto-ended", "quarantined", "disabled",
];

const stop = (paneId: string, reason: StopReason, at: number, lastOutput?: string): PaneStop =>
  ({ paneId, reason, detail: `detail for ${reason}`, at, ...(lastOutput !== undefined ? { lastOutput } : {}) });

/** Ledger scenarios, each `now`-relative so expiry is exact rather than wall-clock. */
type Case = { label: string; existing: PaneStop[]; incoming: PaneStop; now: number };

const T = 1_000_000;
const SUBJECTS: Case[] = [
  { label: "an empty ledger", existing: [], incoming: stop("p1", "failed", T), now: T },
  { label: "a second pane stops", existing: [stop("p1", "failed", T)], incoming: stop("p2", "signalled", T), now: T },
  // REPLACE, don't stack — the nine-stops-in-one-run case.
  { label: "the SAME pane stops again — replaced, not stacked", existing: [stop("p1", "failed", T)], incoming: stop("p1", "signalled", T + 100), now: T + 100 },
  { label: "the same pane stops nine times", existing: Array.from({ length: 8 }, (_, i) => stop("p1", "failed", T + i)), incoming: stop("p1", "signalled", T + 8), now: T + 8 },
  // Expiry.
  { label: "an EXPIRED stop is dropped on the next record", existing: [stop("old", "failed", T - STOP_NOTICE_MS - 1)], incoming: stop("p1", "failed", T), now: T },
  { label: "a stop exactly AT the window edge is expired", existing: [stop("old", "failed", T - STOP_NOTICE_MS)], incoming: stop("p1", "failed", T), now: T },
  { label: "a stop just INSIDE the window survives", existing: [stop("old", "failed", T - STOP_NOTICE_MS + 1)], incoming: stop("p1", "failed", T), now: T },
  // The cap.
  { label: "the ledger is capped", existing: Array.from({ length: MAX_STOPS + 4 }, (_, i) => stop(`pane${i}`, "failed", T)), incoming: stop("new", "failed", T), now: T },
];

describe("stopLedger fixtures", () => {
  it("captures the judgement, the ledger and the log line", () => {
    const next = {
      note: "GENERATED from @/app/console/lib/paneStops — do not hand-edit; see the .gen.test.ts",
      noticeMs: STOP_NOTICE_MS,
      maxStops: MAX_STOPS,
      // Every reason: is it a fault, and what does its log line read like with and without output?
      reasons: REASONS.map((r) => ({
        reason: r,
        fault: isFaultStop(r),
        logWithOutput: stopLogLine(stop("p1", r, T, "the last words")),
        logWithoutOutput: stopLogLine(stop("p1", r, T)),
      })),
      cases: SUBJECTS.map((c) => {
        const after = recordStop(c.existing, c.incoming, c.now);
        return {
          label: c.label,
          existing: c.existing,
          incoming: c.incoming,
          now: c.now,
          after,
          active: activeStops(after, c.now),
        };
      }),
    };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("`finished` is a SUCCESS, and the routine set is exactly five", () => {
    expect(isFaultStop("finished"), "a completed agent is not a fault").toBe(false);
    const routine = REASONS.filter((r) => !isFaultStop(r));
    expect(routine.sort()).toEqual(["app-closed", "auto-ended", "disabled", "finished", "reaped"]);
    expect(REASONS.filter(isFaultStop).sort()).toEqual(["failed", "launcher-failed", "quarantined", "signalled", "unknown"]);
  });

  it("REPLACE, don't stack — nine stops for one pane leave one notice", () => {
    let list: PaneStop[] = [];
    for (let i = 0; i < 9; i++) list = recordStop(list, stop("p1", "failed", T + i), T + i);
    expect(list.filter((s) => s.paneId === "p1")).toHaveLength(1);
    expect(list[list.length - 1].at, "the NEWEST answer is the one kept").toBe(T + 8);
  });

  it("only a FAULT carries its last output into the log line", () => {
    expect(stopLogLine(stop("p1", "finished", T, "chatter")), "quoting a clean session is noise")
      .not.toContain("last output");
    expect(stopLogLine(stop("p1", "signalled", T, "chatter"))).toContain("last output: chatter");
  });

  it("a fault that printed NOTHING says so rather than leaving an absence", () => {
    expect(stopLogLine(stop("p1", "signalled", T))).toContain("(printed nothing)");
  });
});

