// The STOP LEDGER (#a-stopped-session-says-why) — why each pane stopped, kept just long enough to
// tell the user and logged so the answer outlives the telling.
//
// WHY THIS EXISTS AS A MODEL RATHER THAN A BANNER'S LOCAL STATE. A pane can stop for reasons that
// arrive from three different directions, and only together do they answer "why did my worker go
// away":
//   · the PROCESS ended — carried on `pty_exit_` + the pane id from Rust, which knows the exit code, the
//     signal, and whether the cage's launcher failed before the agent ever ran;
//   · the APP stopped it — the idle reaper, worker auto-end, a warden quarantine, a pane disabled;
//   · nothing stopped it and it FINISHED, which must not be reported as a fault.
// A banner owning this would only ever see the direction it happened to subscribe to.
//
// The reason for an app-side stop is the ACTION that ran, so it is recorded at the sink — inside
// `reapPane`, `markPaneEnded`, `markQuarantine`, `setPaneDisabled` — rather than at each of their
// many call sites. One edit per cause, and a new call site cannot forget to report.

/** Why a pane stopped. The first six mirror Rust's `EndReason` on the `pty_exit` payload verbatim
 *  (kebab-case, so the wire spelling and this union are the same string); the rest are app-side
 *  decisions the frontend already knows it made. */
export type StopReason =
  | "finished"        // exit 0 — the agent completed. NOT a fault.
  | "failed"          // a non-zero exit from whatever ran.
  | "signalled"       // killed by a fatal signal (the shell's 128+N).
  | "launcher-failed" // bwrap / systemd-run died before the agent started.
  | "app-closed"      // pty_kill, a project teardown, app exit.
  | "unknown"         // the pty closed and the status could not be read.
  | "reaped"          // the idle reaper reclaimed it (#849).
  | "auto-ended"      // the worker finished its lane and auto-ended (#920).
  | "quarantined"     // the warden hard-paused it (#1102).
  | "disabled";       // the pane was switched off — by the user, or the boot GC.

/** One stop, as the banner shows it and the log records it. */
export interface PaneStop {
  paneId: string;
  reason: StopReason;
  /** One sentence, already phrased for a human. Rust supplies this for a process end. */
  detail: string;
  /** Epoch ms. The banner's own clock — see `activeStops`. */
  at: number;
  /** What the session last PRINTED, when it ended badly (#a-stopped-session-shows-its-last-words).
   *
   *  Rust sanitizes and bounds it before it crosses. Only ever set for a fault: quoting a clean
   *  session's output is how the notice becomes noise. `undefined` on a fault means the session
   *  printed nothing legible, which the banner SAYS rather than rendering an empty quote. */
  lastOutput?: string;
}

/** How long a stop notice stays on screen. The maintainer asked for "5 seconds max just to inform
 *  the user": this is an INFORMATIONAL notice, not a decision, so it must never wait for a click.
 *  The log line is what makes the short life affordable. */
export const STOP_NOTICE_MS = 5_000;

/** How many stops the ledger keeps. Bounded because this is transient state on a hot path: a fleet
 *  relaunch can stop a dozen panes at once, and nothing here is worth unbounded growth. Well above
 *  what can be legible in five seconds, so the cap is a safety floor rather than a policy. */
export const MAX_STOPS = 12;

/** Stops that are NORMAL — a session that finished, or one the app/user deliberately closed.
 *
 *  This split is the whole reason the feature does not become noise. Every session ends eventually,
 *  so a banner that fires on all of them is one the user learns to ignore, and the nine real
 *  failures hide among them. `finished` in particular is a SUCCESS. */
const ROUTINE: readonly StopReason[] = ["finished", "app-closed", "auto-ended", "reaped", "disabled"];

/** Is this stop something went WRONG, as opposed to something ending? */
export function isFaultStop(reason: StopReason): boolean {
  return !ROUTINE.includes(reason);
}

/** The banner tone for a stop. `launcher-failed` is the loudest because the agent never ran at all
 *  and the fix is on the host, not in the session. */
export function stopTone(reason: StopReason): "danger" | "warn" | "neutral" {
  if (reason === "launcher-failed" || reason === "quarantined") return "danger";
  return isFaultStop(reason) ? "warn" : "neutral";
}

/** The short phrase naming the stop, for the banner's lead. Kept separate from `detail` so the
 *  banner can read "PANE stopped: HEADLINE — DETAIL" without Rust having to phrase both halves.
 *
 *  (Written in caps rather than angle brackets on purpose: `emit-records` picks a record's emitted
 *  extension by scanning for an angle-bracketed identifier, and a placeholder in a COMMENT is enough
 *  to make this module emit as `.tsx` — which then breaks the packaged kit's runtime closure, since
 *  it lists modules by their `.ts` path.) */
export function stopHeadline(reason: StopReason): string {
  switch (reason) {
    case "finished": return "finished";
    case "failed": return "the agent exited with an error";
    case "signalled": return "killed";
    case "launcher-failed": return "the sandbox never started";
    case "app-closed": return "closed by the app";
    case "reaped": return "reclaimed while idle";
    case "auto-ended": return "finished its work";
    case "quarantined": return "paused by the warden";
    case "disabled": return "switched off";
    case "unknown": return "stopped for an unknown reason";
  }
}

/**
 * Append a stop, replacing any earlier one for the SAME pane, and drop what has expired.
 *
 * Replacing rather than stacking is load-bearing: the reported worker stopped NINE times in one
 * run, and nine notices for one pane is the same information nine times over while whatever else
 * stopped scrolls out of reach. The newest answer for a pane is the one worth showing.
 *
 * Pure, and takes `now` rather than reading the clock, so expiry is testable without waiting.
 */
export function recordStop(list: readonly PaneStop[], stop: PaneStop, now: number): PaneStop[] {
  const kept = list.filter((s) => s.paneId !== stop.paneId && now - s.at < STOP_NOTICE_MS);
  return [...kept, stop].slice(-MAX_STOPS);
}

/** The stops still inside their notice window, newest first — what the banner renders. */
export function activeStops(list: readonly PaneStop[], now: number): PaneStop[] {
  return list.filter((s) => now - s.at < STOP_NOTICE_MS).sort((a, b) => b.at - a.at);
}

/** The single line written to the app log for a stop. Always written, whether or not a banner was
 *  on screen — the banner lasts five seconds and this is what answers the question afterwards. */
export function stopLogLine(stop: PaneStop): string {
  const base = `pane[${stop.paneId}] stopped · ${stop.reason} · ${stop.detail}`;
  // The last words go in the LOG as well as the banner: the banner lasts five seconds and this is
  // the copy still there tomorrow. Only for a fault, and "printed nothing" is stated rather than
  // left as an absence — a session that died silently is itself the finding.
  if (!isFaultStop(stop.reason)) return base;
  return `${base} · last output: ${stop.lastOutput ?? "(printed nothing)"}`;
}

/**
 * Order stops for a collapsed notice: FAULTS FIRST, then newest.
 *
 * A fault carries its last words, and once the pane is recreated nothing else in the app has them. So
 * when several stops share one banner, the faults must be the rows that survive a glance — burying an
 * `exit=1` under six routine closes is how the one line worth reading goes unread.
 */
export function stopsForNotice(list: readonly PaneStop[], now: number): PaneStop[] {
  return activeStops(list, now)
    .slice()
    .sort((a, b) => {
      const fa = isFaultStop(a.reason) ? 0 : 1;
      const fb = isFaultStop(b.reason) ? 0 : 1;
      return fa !== fb ? fa - fb : b.at - a.at;
    });
}

/**
 * The one-line summary for a collapsed notice — "6 sessions stopped · 5 closed by the app, 1 reclaimed
 * while idle".
 *
 * Counted BY REASON rather than listing pane ids: the ids are in the rows below, and the question this
 * line answers is "what happened to my sessions", which is a reason, not a roster. Reasons appear in
 * the order `stopsForNotice` puts them, so the fault is named first here too.
 */
export function stopSummary(stops: readonly PaneStop[]): string {
  if (stops.length === 0) return "";
  const counts = new Map<StopReason, number>();
  for (const s of stops) counts.set(s.reason, (counts.get(s.reason) ?? 0) + 1);
  const parts = [...counts.entries()].map(([reason, n]) => `${n} ${stopHeadline(reason)}`);
  const noun = stops.length === 1 ? "session" : "sessions";
  return `${stops.length} ${noun} stopped · ${parts.join(", ")}`;
}
